import "./kbd.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type KbdProps = ComponentProps<"kbd">;

export function Kbd({ className, ...rest }: KbdProps) {
  return <kbd className={cx("ns-kbd", className)} {...rest} />;
}

@layer components {
  .ns-kbd {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.5em;
    padding: 0 var(--space-2, 0.31rem);
    border: 1px solid var(--face-line, #626262);
    border-radius: var(--radius, 0.4rem);
    background: var(--face);
    background-clip: padding-box;
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    color: var(--text-heading, #111);
    font: inherit;
    font-size: var(--type-mono, 0.875rem);
    font-family: var(--font-mono, "DM Mono", ui-monospace, monospace);
    line-height: var(--leading-tight, 1.25);
  }
}
